// 画像最適化：WPが生成済みの縮小版を srcset で出し分け（原寸1〜3MB→数十KB）。og:image等のmetaは原寸のまま
const VAR={'2026/04/glow_img-08':[1477,1108],'2026/04/glow_img-05':[1477,1108],'2026/04/glow_img-10':[1920,1280],'2026/05/staff_3':[1477,1108],'2026/04/glow_img-03':[1477,1108],'2026/04/glow_img-06':[1477,1108],'2026/04/glow_img-09':[1477,1108]};
const optImgs=h=>h.replace(/<img src="\/wp-content\/uploads\/([^"]+)\.jpg"([^>]*)>/g,(m,n,rest)=>{const d=VAR[n];if(!d)return m;const v=w=>`/wp-content/uploads/${n}-${w}x${Math.round(d[1]*w/d[0])}.jpg`;const hero=/fetchpriority/.test(rest);if(/class="sm"/.test(rest))return `<img src="${v(300)}" srcset="${v(300)} 300w, ${v(768)} 768w" sizes="250px"${rest}>`;return `<img src="${v(1024)}" srcset="${v(300)} 300w, ${v(768)} 768w, ${v(1024)} 1024w" sizes="${/class="ph3"/.test(rest)?'(max-width:820px) 46vw, 300px':hero?'(max-width:820px) 100vw, 520px':'(max-width:720px) 100vw, 640px'}"${rest}>`});
